def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the diagonal cycle from the well-populated central region.
    best = None
    for p in range(2, 11):
        counts = [Counter() for _ in range(p)]
        for r in range(6, h):
            for c in range(6, w):
                v = grid[r][c]
                if v:
                    counts[(r + c) % p][v] += 1
        mapping = [cnt.most_common(1)[0][0] if cnt else 0 for cnt in counts]
        n = sum(sum(cnt.values()) for cnt in counts)
        correct = sum(cnt[mapping[i]] for i, cnt in enumerate(counts))
        score = correct / n if n else 0
        # Prefer the shorter cycle in case of a tie.
        score -= p * 1e-5
        if best is None or score > best[0]:
            best = (score, p, mapping)

    _, p, mapping = best
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % p]
    return out
